8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * Apart from the one added prop described in the next paragraph, the differences from the base
14	 * file are the TypeScript annotations below, house formatting, and a small number of
15	 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
16	 * `Deviation from the base file` comment.
17	 *
18	 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
19	 * faithful port with the same `forwardRef` behaviour. It carries exactly one additive optional
20	 * prop over the base file's surface — `renderHeader`, documented on `ProductViewProps` below.
21	 * It is behaviour-preserving when omitted (its default renders the same private
22	 * `ProductViewHeader` the base file renders inline), and `renderHeader` has zero occurrences in
23	 * the base package, so none of the four base modules that import ProductView — product-view-modal
24	 * (index and bundle), bonus-product-view-modal, and pages/product-detail — passes it or is
25	 * affected by it. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see
26	 * the note at the foot of the file.)
27	 */
28	
29	import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
30	import { useLocation } from 'react-router-dom';
31	import { useIntl, FormattedMessage } from 'react-intl';
32	
33	import {
34	  Flex,
35	  Heading,
36	  Button,
37	  Skeleton,
38	  AspectRatio,
39	  Box,
40	  Text,
41	  VStack,
42	  Fade,
43	  Stack,
44	  Radio,
45	  RadioGroup,
46	  useTheme,
47	} from '@salesforce/retail-react-app/app/components/shared/ui';
48	
49	// Constants
50	const DELIVERY_OPTIONS = {
51	  DELIVERY: 'delivery',
52	  PICKUP: 'pickup',
53	};
54	import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
55	import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
56	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
57	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
58	import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
59	import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
60	
61	// project components
62	// Base compact gallery — still used for imageSize="sm" callers (product-view-modal's
63	// quick-view and bundle paths, bonus-product-view-modal). See the imageSize destructuring
64	// below for why this stays alongside ZimmProductGallery rather than being replaced entirely.
65	import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
66	import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
67	// SFCC-731 — Zimmermann gallery, PDP path only (imageSize="md", the default). Relative, not
68	// the SFCC base `image-gallery` path: this component isn't shadowing that base module (see
69	// zimmProductGallery's own doc comment for why), so there is nothing for the overrides
70	// resolver to redirect here.
71	import { ZimmProductGallery } from '../ui-kits/organisms/zimmProductGallery';
72	import { ZimmGalleryOverlay } from '../ui-kits/organisms/zimmGalleryOverlay';
73	import { GALLERY_ITEM_ASPECT_RATIO } from '../ui-kits/atoms/zimmMediaTile/zimmMediaTile.css';
74	import { mapImageGroupsToGalleryMedia } from './mapImageGroupsToGalleryMedia';
75	// SFCC-708 — related-colour swatches, same helper product-detail/index.tsx uses to build its
76	// own combined "Colour:" group. Reused here so the overlay shows the identical offered-colour
77	// set, not a narrower natural-variants-only one.
78	import { buildRelatedSwatches, type RelatedSwatch } from '../../pages/product-detail/productInfo';
79	import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
80	
81	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
82	import Link from '@salesforce/retail-react-app/app/components/link';
83	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
84	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
85	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
86	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
87	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
88	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
89	import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
90	import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
91	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
92	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
93	import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
94	import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
95	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
96	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
97	
98	/*
99	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
100	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
101	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
102	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
103	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
104	 *
105	 * Substituting them is a follow-up rather than part of this PR only because it also removes
106	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
107	 * across every commit.
108	 */
109	type SfccProduct = any;
110	type SfccVariant = any;
111	type SfccCategory = any;
112	type SfccPriceData = any;
113	
114	/** One selectable value of a variation attribute, as the base hooks shape it. */
115	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
116	
117	/** A variation attribute (colour, size, ...) with its selectable values. */
118	type SfccVariationAttribute = {
119	  id: string;
120	  name?: string;
121	  selectedValue?: SfccVariationValue;
122	  values: SfccVariationValue[];
123	};
124	
125	/** SFCC variation attribute ID for the colour attribute. */
126	export const SFCC_COLOUR_ATTRIBUTE_ID = 'color';
127	
128	/** The per-child orderability record ProductView writes back to its parent. */
129	export type ChildProductOrderability = {
130	  showInventoryMessage?: boolean;
131	  unfulfillable?: boolean;
132	  isOutOfStock?: boolean;
133	  stockLevel?: number;
134	  productName?: string;
135	};
136	
137	export type ProductViewHeaderProps = {
138	  name?: string;
139	  currency?: string;
140	  priceData?: SfccPriceData;
141	  category?: SfccCategory[];
142	  product?: SfccProduct;
143	  isProductPartOfBundle?: boolean;
144	};
145	
146	/*
147	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
148	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
149	 * from the default implementation the base file supplies.
150	 */
151	type ProductViewProps = {
152	  product?: SfccProduct;
153	  category?: SfccCategory[];
154	  showFullLink?: boolean;
155	  imageSize?: 'sm' | 'md';
156	  isWishlistLoading?: boolean;
157	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
158	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
159	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
160	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
161	  isProductLoading?: boolean;
162	  isProductPartOfSet?: boolean;
163	  isProductPartOfBundle?: boolean;
164	  childOfBundleQuantity?: number;
165	  childProductOrderability?: Record<string, ChildProductOrderability>;
166	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
167	  isBasketLoading?: boolean;
168	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
169	  validateOrderability?: (
170	    variant: SfccVariant,
171	    product: SfccProduct,
172	    quantity: number,
173	    stockLevel: number,
174	  ) => boolean | undefined;
175	  showImageGallery?: boolean;
176	  setSelectedBundleQuantity?: (quantity: number) => void;
177	  selectedBundleParentQuantity?: number;
178	  pickupInStore?: boolean;
179	  setPickupInStore?: (checked: boolean) => void;
180	  onOpenStoreLocator?: () => void;
181	  showDeliveryOptions?: boolean;
182	  customButtons?: React.ReactElement[];
183	  promotionId?: string;
184	  maxOrderQuantity?: number | null;
185	  imageGalleryFooter?: React.ReactNode;
186	  alignItems?: string;
187	  controlledVariationValues?: Record<string, string> | null;
188	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
189	  /**
190	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
191	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
192	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
193	   * them. Defaults to rendering that same private header, so every existing caller — cart,
194	   * wishlist, bonus-product — is byte-identical unless it opts in.
195	   *
196	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
197	   * twice with the same arguments. Keep it pure.
198	   */
199	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
200	  /**
201	   * Render slot for overriding how a single variation attribute is displayed. When provided,
202	   * the returned node replaces the base SwatchGroup for that attribute. Return `undefined` (or
203	   * omit the prop) to fall through to `renderDefaultVariationAttribute` — the base SwatchGroup
204	   * rendering. The PDP uses this to inject `ZimmColourSwatchGroup` for the colour attribute;
205	   * the quick-view modal omits it and keeps the base SwatchGroup for all attributes.
206	   */
207	  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
208	  /**
209	   * The second Zimmermann addition to this component's prop surface (SFCC-736/195). Renders
210	   * after the CTAs (`renderActionButtons()`), inside the same column — Figma's "Find in
211	   * Boutique" link and the Details & Care / Size & Fit / Shipping & Returns / Assistance
212	   * drawer-trigger rows. A plain node, like the existing `imageGalleryFooter` slot, not a
213	   * render-prop like `renderHeader`: this content needs none of ProductView's own render-time
214	   * data, it is driven entirely by state the caller (`product-detail/index.tsx`) already owns.
215	   * `null` by default, so every existing caller (cart, wishlist, bonus-product) is unaffected.
216	   */
217	  footerLinks?: React.ReactNode;
218	};
219	
220	/*
221	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
222	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
223	 * pages/product-detail).
224	 */
225	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
226	
227	/**
228	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
229	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
230	 * below. A consumer names it as the `this` parameter of its ref callback —
231	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
232	 * as written; no assertion is required at the prop site.
233	 */
234	export type ProductViewRefScope = {
235	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
236	};
237	
238	const ProductViewHeader = ({
239	  name,
240	  currency,
241	  priceData,
242	  category,
243	  product,
244	  isProductPartOfBundle,
245	}: ProductViewHeaderProps) => {
246	  return (
247	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
248	      {category && (
249	        <Skeleton isLoaded={category} minWidth={64}>
250	          <Breadcrumb categories={category} />
251	        </Skeleton>
252	      )}
253	
254	      {/* Title */}
255	      <Skeleton isLoaded={name}>
256	        <Heading fontSize="2xl">{`${name}`}</Heading>
257	      </Skeleton>
258	
259	      {!isProductPartOfBundle && (
260	        <>
261	          <Skeleton isLoaded={priceData?.currentPrice}>
262	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
263	          </Skeleton>
264	
265	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
266	        </>
267	      )}
268	    </VStack>
269	  );
270	};
271	
272	const ButtonWithRegistration = withRegistration(Button);
273	
274	/**
275	 * Render a product detail view that includes name, image gallery, price,
276	 * variant selections, action buttons
277	 */
278	
279	const ProductView = forwardRef(
280	  (
281	    {
282	      product,
283	      category,
284	      showFullLink = false,
285	      // SFCC-731 review finding (CodeRabbit, 2026-09-02): ZimmProductGallery has no
286	      // size-variant concept, so this was briefly a no-op — a real regression for the
287	      // unmodified base callers that pass imageSize="sm" (product-view-modal's quick-view and
288	      // bundle paths, bonus-product-view-modal), whose compact-modal gallery would otherwise
289	      // have silently switched to the full PDP gallery. Fixed by branching on it below: 'sm'
290	      // keeps the base ImageGallery exactly as before, ZimmProductGallery only renders for the
291	      // PDP's own 'md' (default) path.
292	      imageSize = 'md',
293	      isWishlistLoading = false,
294	      addToCart,
295	      updateCart,
296	      addToWishlist,
297	      updateWishlist,
298	      isProductLoading,
299	      isProductPartOfSet = false,
300	      isProductPartOfBundle = false,
301	      childOfBundleQuantity = 0,
302	      childProductOrderability,
303	      setChildProductOrderability,
304	      isBasketLoading = false,
305	      onVariantSelected = () => {},
306	      validateOrderability = (variant, product, quantity, stockLevel) => {
307	        if (isProductLoading) return false;
308	
309	        // If product has variations, a variant must be selected
310	        if (product?.variationAttributes?.length > 0 && !variant) {
311	          return false;
312	        }
313	
314	        // Check if product (either variant or standard) is orderable and if quantity is valid
315	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
316	      },
317	      showImageGallery = true,
318	      setSelectedBundleQuantity = () => {},
319	      selectedBundleParentQuantity = 1,
320	      pickupInStore = false,
321	      setPickupInStore = () => {},
322	      onOpenStoreLocator = () => {},
323	      showDeliveryOptions = true,
324	      customButtons = [],
325	      maxOrderQuantity = null,
326	      imageGalleryFooter = null,
327	      controlledVariationValues = null,
328	      onVariationChange = null,
329	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
330	      renderVariationAttribute,
331	      footerLinks = null,
332	    }: ProductViewProps,
333	    ref: ProductViewRef,
334	  ) => {
335	    const { currency: activeCurrency } = useCurrency();
336	    const showToast = useToast();
337	    const intl = useIntl();
338	    const location = useLocation();
339	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
340	    const {
341	      isOpen: isAddToCartModalOpen,
342	      onOpen: onAddToCartModalOpen,
343	      onClose: onAddToCartModalClose,
344	    } = useAddToCartModalContext();
345	
346	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
347	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
348	
349	    const theme = useTheme();
350	    const { confirmingBasket } = useSFPayments();
351	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
352	    const {
353	      showLoading,
354	      showInventoryMessage,
355	      inventoryMessage,
356	      quantity,
357	      minOrderQuantity,
358	      setQuantity,
359	      variant,
360	      variationParams,
361	      variationAttributes,
362	      stockLevel,
363	      stepQuantity,
364	      isOutOfStock,
365	      unfulfillable,
366	      isSelectedStoreOutOfStock,
367	      selectedStore,
368	    } = useDerivedProduct(
369	      product,
370	      isProductPartOfSet,
371	      isProductPartOfBundle,
372	      pickupInStore,
373	      controlledVariationValues,
374	      onVariationChange,
375	    );
376	    const priceData = useMemo(() => {
377	      return getPriceData(product, { quantity });
378	    }, [product, quantity]);
379	    // SFCC-731 AC 15 — gallery overlay's own "Also available in" swatch row. Combines natural
380	    // same-master variants with SFCC-708's cross-master related swatches, matching
381	    // product-detail/index.tsx's own `allValues` pattern exactly — the overlay must offer the
382	    // same colour set the main PDP sidebar does, not a narrower one (SFCC-708's Jira thread).
383	    const colourAttr = variationAttributes?.find(
384	      (attr: SfccVariationAttribute) => attr.id === SFCC_COLOUR_ATTRIBUTE_ID,
385	    );
386	    const naturalColourValues =
387	      colourAttr?.values.map((v: SfccVariationValue) => {
388	        const image = v.image as unknown as { disBaseLink?: string; link?: string } | undefined;
389	        return {
390	          value: v.value ?? '',
391	          name: v.name,
392	          imageUrl: image?.disBaseLink || image?.link || '',
393	          href: v.href,
394	          orderable: v.orderable ?? true,
395	        };
396	      }) ?? [];
397	    const relatedColourValues = buildRelatedSwatches(
398	      (product?.c_relatedSwatches ?? []) as RelatedSwatch[],
399	      productUrlBuilder,
400	      SFCC_COLOUR_ATTRIBUTE_ID,
401	    );
402	    const colourValues = [...naturalColourValues, ...relatedColourValues];
403	    const selectedColourValue = colourAttr?.selectedValue?.value;
404	    const canAddToWishlist = !isProductLoading;
405	    const isProductASet = product?.type?.set;
406	    const isProductABundle = product?.type?.bundle;
407	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
408	    const [pickupEnabled, setPickupEnabled] = useState(false);
409	    // SFCC-731 AC 12-25 — the expanded-state gallery overlay's own open state, owned here rather
410	    // than threaded in as a prop (the old `onOpenGallery` pass-through was left unwired by every
411	    // caller — see git history). Self-contained to the `imageSize === 'md'` branch below, which
412	    // is the only place ZimmProductGallery (and now ZimmGalleryOverlay) renders at all.
413	    const [isGalleryOverlayOpen, setIsGalleryOverlayOpen] = useState(false);
414	    const storeName = selectedStore?.name;
415	    const inventoryId = selectedStore?.inventoryId;
416	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
417	
418	    const { disableButton, customInventoryMessage } = useMemo(() => {
419	      let shouldDisableButton = showInventoryMessage;
420	      let currentInventoryMsg = '';
421	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
422	        // if any of the children are not orderable, it will disable the add to cart button
423	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
424	          return childProductOrderability[key].showInventoryMessage;
425	        });
426	        shouldDisableButton = !!unavailableChildProductKey;
427	        if (unavailableChildProductKey) {
428	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
429	          if (unavailableChildProduct.unfulfillable) {
430	            currentInventoryMsg = intl.formatMessage(
431	              {
432	                defaultMessage: 'Only {stockLevel} left for {productName}!',
433	                id: 'use_product.message.inventory_remaining_for_product',
434	              },
435	              {
436	                stockLevel: unavailableChildProduct.stockLevel,
437	                productName: unavailableChildProduct.productName,
438	              },
439	            );
440	          }
441	          if (unavailableChildProduct.isOutOfStock) {
442	            currentInventoryMsg = intl.formatMessage(
443	              {
444	                defaultMessage: 'Out of stock for {productName}',
445	                id: 'use_product.message.out_of_stock_for_product',
446	              },
447	              { productName: unavailableChildProduct.productName },
448	            );
449	          }
450	        }
451	      }
452	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
453	    }, [showInventoryMessage, childProductOrderability]);
454	
455	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
456	      const { scrollErrorIntoView = true } = opts;
457	      // Validate that all attributes are selected before proceeding.
458	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
459	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
460	      const scrollToError = showError && scrollErrorIntoView;
461	
462	      toggleShowOptionsMessage(showError);
463	
464	      if (scrollToError) {
465	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
466	        // while guarding it in `prepareBasket` below; the two only differ if the error
467	        // container has not mounted, where the base throws.
468	        errorContainerRef.current?.scrollIntoView({
469	          behavior: 'smooth',
470	          block: 'center',
471	        });
472	      }
473	
474	      return hasValidSelection;
475	    };
476	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
477	
478	    // prepareBasket is used to prepare the basket for express payments
479	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
480	    const prepareBasket = useCallback(async () => {
481	      // Validate that all attributes are selected before proceeding
482	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
483	      let errorMessage = '';
484	
485	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
486	        toggleShowOptionsMessage(true);
487	        if (errorContainerRef.current) {
488	          errorContainerRef.current.scrollIntoView({
489	            behavior: 'smooth',
490	            block: 'center',
491	          });
492	        }
493	        errorMessage = intl.formatMessage({
494	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
495	          id: 'product_view.prepareBasket',
496	        });
497	
498	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
499	        error.isValidationError = true;
500	        throw error;
501	      }
502	
503	      // Clean up temporary baskets before creating a new one
504	      await cleanupTemporaryBaskets();
505	
506	      // Create a new temporary basket
507	      const newBasket = await createBasket({
508	        parameters: {
509	          temporary: true,
510	        },
511	        body: {},
512	      });
513	
514	      const selectedProduct = variant || product;
515	      // Use variant's productId if variant is selected, otherwise use product's id
516	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
517	
518	      if (!productIdToUse) {
519	        errorMessage = intl.formatMessage({
520	          defaultMessage: 'Unable to determine product ID for basket',
521	          id: 'product_view.prepareBasket',
522	        });
523	        throw new Error(errorMessage);
524	      }
525	      // Add the product to the temporary basket
526	      const basketWithItem = await addItemToBasket({
527	        // SDK param widening — `newBasket` is the basket just created above.
528	        parameters: { basketId: newBasket.basketId as string },
529	        body: [
530	          {
531	            productId: productIdToUse,
532	            quantity: quantity,
533	          },
