    values: [v('raspberry', 'Raspberry'), v('ivory', 'Ivory'), v('navy', 'Navy')],
    selectedValue: 'raspberry',
  },
};

/**
 * Circle variant with 7 colours — exercises the same SWATCHES_PER_PAGE=4 pagination as the
 * square variant, confirmed for circles too via the same Figma node's `showColourOption3`/
 * `showColourOption4`/`showPagination` props.
 */
export const CircleVariantPaginated: Story = {
  args: {
    label: 'Also available in',
    appendColon: false,
    variant: 'circle',
    values: [
      v('raspberry', 'Raspberry'),
      v('ivory', 'Ivory'),
      v('navy', 'Navy'),
      v('black', 'Black'),
      v('sage', 'Sage'),
      v('coral', 'Coral'),
      v('lilac', 'Lilac'),
    ],
    selectedValue: 'raspberry',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const nextBtn = canvas.getByRole('button', { name: 'Next colours' });
    await expect(nextBtn).toBeEnabled();
    await userEvent.click(nextBtn);
    await expect(await canvas.findAllByRole('radio')).toHaveLength(7);
    await expect(canvas.getByRole('radio', { name: 'Sage' })).toBeInTheDocument();
  },
};

/**
 * Keyboard navigation — ArrowRight/Left move colour selection without mouse.
 *
 * Swatches have no `href` so ArrowKey presses call `onSelect` (linkless path) rather than
 * `history.push` — this lets the `play` assert on the emitted value without depending on
 * router state that the story does not control.
 */
export const KeyboardNavigation: Story = {
  args: {
    label: 'Colour',
    values: [
      v('raspberry', 'Raspberry', { href: undefined }),
      v('ivory', 'Ivory', { href: undefined }),
      v('navy', 'Navy', { href: undefined }),
    ],
    selectedValue: 'raspberry',
    onSelect: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const swatches = canvas.getAllByRole('radio');

    // Start focused on Raspberry (index 0) and navigate right → Ivory (index 1).
    swatches[0].focus();
    await userEvent.keyboard('{ArrowRight}');
    await expect(args.onSelect).toHaveBeenCalledWith('ivory');

    // ArrowLeft from Raspberry wraps to the last swatch (Navy, index 2).
    await userEvent.keyboard('{ArrowLeft}');
    await expect(args.onSelect).toHaveBeenCalledWith('navy');
  },
};

