11	type UseZimmModalReturn = {
12	  /** False until after the first client render, so the dialog is not rendered during SSR. */
13	  mounted: boolean;
14	  /** Attach to the element that bounds the dialog's own content — kept for existing markup
15	   *  compatibility. Chakra's Modal now traps focus across the whole ModalContent itself, so this
16	   *  ref is no longer load-bearing. */
17	  trapRef: React.RefObject<HTMLElement>;
18	  /** Attach to the wrapper around the first field — kept for existing markup compatibility.
19	   *  Chakra's Modal now auto-focuses the first focusable element on open by default. */
20	  firstFocusRef: React.RefObject<HTMLDivElement>;
21	};
